cpp.setup:
auto* control = new fluent::collections::StackView(%PARENT%);
auto* page = new fluent::layout::Card(control);
auto* layout = new QVBoxLayout(page);
layout->setContentsMargins(20, 16, 20, 16);
layout->setSpacing(8);
auto* pageTitle = new fluent::textfields::Label(QStringLiteral("Overview"), page);
pageTitle->setFluentTypography(Typography::FontRole::Subtitle);
layout->addWidget(pageTitle);
auto* pageSummary = new fluent::textfields::Label(QStringLiteral("Browse workspace summary and open the detail page to inspect stack navigation."), page);
pageSummary->setWordWrap(true);
pageSummary->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
layout->addWidget(pageSummary);
layout->addStretch();
auto* next = new fluent::basicinput::Button(QStringLiteral("Open details"), page);
next->setFluentStyle(fluent::basicinput::Button::Accent);
layout->addWidget(next, 0, Qt::AlignLeft);
auto* details = new fluent::layout::Card(control);
details->setObjectName(QStringLiteral("playgroundDetails"));
auto* detailsLayout = new QVBoxLayout(details);
detailsLayout->setContentsMargins(20, 16, 20, 16);
detailsLayout->setSpacing(8);
auto* detailsTitle = new fluent::textfields::Label(QStringLiteral("Details"), details);
detailsTitle->setFluentTypography(Typography::FontRole::Subtitle);
detailsLayout->addWidget(detailsTitle);
auto* detailsSummary = new fluent::textfields::Label(QStringLiteral("Pushed onto the stack. Use Back or the property panel to return to the overview."), details);
detailsSummary->setWordWrap(true);
detailsSummary->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
detailsLayout->addWidget(detailsSummary);
detailsLayout->addStretch();
auto* back = new fluent::basicinput::Button(QStringLiteral("Back"), details);
detailsLayout->addWidget(back, 0, Qt::AlignLeft);
details->hide();
QObject::connect(next, &QAbstractButton::clicked, control, [control, details] { control->push(details, fluent::WidgetOwnership::Reparented); });
QObject::connect(back, &QAbstractButton::clicked, control, [control] { control->pop(); });
control->push(page, fluent::WidgetOwnership::Owned);
